import { db } from "@/lib/firebase";
import { doc, getDoc } from "firebase/firestore";

export async function GET(req, { params }) {
  try {
    console.log("Params recibidos:", params);
    console.log("Request URL:", req.url);

    const { id } = params;

    if (!id) {
      console.error("Falta el parámetro id en params:", params);
      return new Response(
        JSON.stringify({ error: "Falta el parámetro id del paciente", params }),
        { status: 400 }
      );
    }

    const pacienteDocRef = doc(
      db,
      "pacientes",
      "lista",
      "nombresPacientes",
      id
    );
    const pacienteDoc = await getDoc(pacienteDocRef);

    if (!pacienteDoc.exists()) {
      return new Response(
        JSON.stringify({ error: "No se encontró el paciente" }),
        { status: 404 }
      );
    }

    const datos = pacienteDoc.data();
    console.log("Datos del paciente:", datos); // Debug

    return new Response(JSON.stringify(datos), { status: 200 });
  } catch (error) {
    console.error("Error obteniendo datos del paciente:", error);
    return new Response(JSON.stringify({ error: error.message }), {
      status: 500,
    });
  }
}
